"""Run identity and durable artifact access shared by all entry points."""

import json
import os
import re
from pathlib import Path
from tempfile import NamedTemporaryFile

from .settings import ROOT

RUNS_DIR = Path(os.environ.get("QA_RUNS_DIR", ROOT / "runs")).expanduser().resolve()
INVALID_RUN_ID = "Expected a 32-character lowercase hexadecimal run ID"


def valid_run_id(value: object) -> bool:
    """Accept only identifiers generated by the runner."""
    return isinstance(value, str) and re.fullmatch(r"[0-9a-f]{32}", value) is not None


def run_directory(run_id: str) -> Path:
    """Validate identity and reject run-directory links outside artifact storage."""
    if not valid_run_id(run_id):
        raise ValueError(INVALID_RUN_ID)
    root = RUNS_DIR.resolve()
    folder = root / run_id
    if folder.resolve().parent != root:
        raise ValueError("Run directory escapes artifact storage")
    return folder


def _atomic_write(path: Path, text: str) -> None:
    """Replace a complete file atomically and clean up failed writes."""
    temporary = None
    try:
        with NamedTemporaryFile(
            mode="w", encoding="utf-8", dir=path.parent, prefix=f".{path.name}.", delete=False
        ) as stream:
            temporary = Path(stream.name)
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        temporary.replace(path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def save_summary(result: dict) -> None:
    """Write readable files first and publish the canonical JSON summary last."""
    folder = run_directory(result["run_id"])
    folder.mkdir(parents=True, exist_ok=True)
    _atomic_write(folder / "report.md", result["report"] + "\n")
    drafts = result.get("bug_reports") or {}
    if drafts:
        (folder / "bug-reports").mkdir(exist_ok=True)
    for cluster_id, text in drafts.items():
        if re.fullmatch(r"C\d+(-model)?", cluster_id):
            _atomic_write(folder / "bug-reports" / f"{cluster_id}.md", text)
    _atomic_write(folder / "summary.json", json.dumps(result, indent=2) + "\n")


def previous_summaries(suite: str, exclude: str | None = None, limit: int = 10) -> list[dict]:
    """Return earlier readable summaries of one suite, newest first, for history."""
    try:
        folders = [folder for folder in RUNS_DIR.iterdir() if valid_run_id(folder.name)]
    except OSError:
        return []
    summaries = []
    for folder in folders:
        if folder.name == exclude:
            continue
        try:
            summary = read_summary(folder.name)
        except (OSError, ValueError):
            continue  # Old runs without a summary are not history.
        if summary.get("suite", "unit") == suite and summary.get("started_at"):
            summaries.append(summary)
    summaries.sort(key=lambda summary: summary["started_at"], reverse=True)
    return summaries[:limit]


def read_summary(run_id: str) -> dict:
    """Read evidence without executing tests or trusting mismatched metadata."""
    path = run_directory(run_id) / "summary.json"
    result = json.loads(path.read_text(encoding="utf-8"))
    if (
        not isinstance(result, dict)
        or result.get("run_id") != run_id
        or not isinstance(result.get("report"), str)
        or result.get("status") not in ("passed", "unsuccessful", "timeout", "launch_error")
    ):
        raise ValueError("Invalid saved summary or mismatched run ID")
    return result
